// Exact-match only: returns the stat whose n equals the captured count, or null.
// (Named for what it does — there is no nearest-match fallback. Callers must
// handle null rather than assume a stat always comes back.)
export function findExactStat(themeStats, capturedCount) {
  if (!themeStats || themeStats.length === 0) return null;
  return themeStats.find(s => s.n === capturedCount) || null;
}
